/**
 * @summary Top homestays by readiness score
 */
export const getGetTopHomestaysUrl = (params?: GetTopHomestaysParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/insights/top-homestays?${stringifiedParams}`
    : `/api/insights/top-homestays`;
};

export const getTopHomestays = async (
  params?: GetTopHomestaysParams,
  options?: RequestInit,
): Promise<TopHomestay[]> => {
  return customFetch<TopHomestay[]>(getGetTopHomestaysUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetTopHomestaysQueryKey = (params?: GetTopHomestaysParams) => {
  return [`/api/insights/top-homestays`, ...(params ? [params] : [])] as const;
};

